ing: EdgeInsets.zero, leading: CircleAvatar(backgroundColor: teal.withOpacity(.12), foregroundColor: teal, child: Text(initials(s.name))), title: Text(s.name, style: const TextStyle(fontWeight: FontWeight.bold)), subtitle: Text(s.course), trailing: Text(prettyDate(s.enrollmentDate), style: const TextStyle(fontSize: 11, color: Colors.grey)))).toList())), const SizedBox(height: 20), _panel('Add a new student', Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Keep the directory fresh with a complete enrollment profile.', style: TextStyle(color: Colors.grey)), const SizedBox(height: 14), OutlinedButton.icon(onPressed: showStudent, icon: const Icon(Icons.add), label: const Text('Start new record'))]))])); }
  Widget _metric(String label, int value, String note, IconData icon) => Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Icon(icon, color: teal), const Spacer(), Text('$value', style: const TextStyle(fontSize: 28, fontWeight: FontWeight.bold)), Text(label, style: const TextStyle(fontWeight: FontWeight.bold)), Text(note, style: const TextStyle(fontSize: 11, color: Colors.grey))])));
