  List<Student> get filtered => students.where((s) => (query.isEmpty || '${s.name} ${s.rollNo} ${s.email}'.toLowerCase().contains(query.toLowerCase())) && (course == 'All courses' || s.course == course) && (status == 'All statuses' || s.status == status)).toList();
