  Widget _studentCard(Student s) => Card(child: ListTile(isThreeLine: true, leading: CircleAvatar(backgroundColor: teal.withOpacity(.12), foregroundColor: teal, child: Text(initials(s.name))), title: Text(s.name, style: const TextStyle(fontWeight: FontWeight.bold)), subtitle: Text('${s.rollNo}\n${s.course}\n${s.email}  •  ${s.phone}'), trailing: PopupMenuButton<String>(onSelected: (v) { if (v == 'edit') showStudent(s); else confirmDelete(s); }, itemBuilder: (_) => const [PopupMenuItem(value: 'edit', child: Text('Edit')), PopupMenuItem(value: 'delete', child: Text('Delete'))])));
  Future<void> showStudent([Student? existing]) async { final result = await showDialog<Student>(context: context, builder: (_) => StudentDialog(student: existing, courses: courses)); if (result != null) { setState(() { if (existing == null) students.insert(0, result); else { final i = students.indexWhere((s) => s.id == existing.id); students[i] = result; } }); await save(); }}
